import { Ui } from "foldkit";

export const { view } = Ui.Button;

export type ButtonAttributes<ParentMessage> =
  Ui.Button.ButtonAttributes<ParentMessage>;
export type ViewConfig<ParentMessage> = Ui.Button.ViewConfig<ParentMessage>;

export {
  buttonClassName,
  destructiveButtonClassName,
  secondaryButtonClassName,
} from "./view";

export const buttonClassName =
  "inline-flex cursor-pointer items-center gap-2 rounded-lg bg-accent-600 px-3 py-2 text-base font-semibold text-white shadow-sm transition-colors hover:not-data-[disabled]:bg-accent-600/85 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const secondaryButtonClassName =
  "inline-flex cursor-pointer items-center gap-2 rounded-lg border border-gray-300 bg-white px-3 py-2 text-base font-semibold text-gray-900 shadow-sm transition-colors hover:not-data-[disabled]:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const destructiveButtonClassName =
  "inline-flex cursor-pointer items-center gap-2 rounded-lg bg-red-600 px-3 py-2 text-base font-semibold text-white shadow-sm transition-colors hover:not-data-[disabled]:bg-red-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

import { Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { describe, test } from "vitest";

import * as Button from "./index";

const ClickedButton = m("ClickedButton");

const Model = S.Struct({
  count: S.Number,
});

type Model = typeof Model.Type;

const Message = S.Union([ClickedButton]);
type Message = typeof Message.Type;

const initialModel: Model = { count: 0 };

const update = (model: Model): readonly [Model, []] => [
  { count: model.count + 1 },
  [],
];

const view = (model: Model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-2")],
    [
      Button.view<Message>({
        onClick: ClickedButton(),
        toView: (attributes) =>
          h.button(
            [...attributes.button, h.Class(Button.buttonClassName)],
            ["Save changes"]
          ),
      }),
      h.p([], [`Clicked ${model.count} times`]),
    ]
  );
};

const disabledView = (): Html => {
  const h = html<Message>();

  return Button.view<Message>({
    isDisabled: true,
    toView: (attributes) =>
      h.button(
        [...attributes.button, h.Class(Button.buttonClassName)],
        ["Disabled"]
      ),
  });
};

describe("Button registry view", () => {
  test("dispatches click messages", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("button", { name: "Save changes" })).toExist(),
      Scene.expect(Scene.text("Clicked 0 times")).toExist(),
      Scene.click(Scene.role("button", { name: "Save changes" })),
      Scene.expect(Scene.text("Clicked 1 times")).toExist()
    );
  });

  test("supports disabled native button state", () => {
    Scene.scene(
      { update, view: disabledView },
      Scene.with(initialModel),
      Scene.expect(Scene.role("button", { name: "Disabled" })).toBeDisabled()
    );
  });
});
